package purchase

import (
	"fmt"
	"sort"

	"github.com/witsaba/paca/packages/domain/business"
	"github.com/witsaba/paca/packages/domain/ingredient"
	"github.com/witsaba/paca/packages/domain/ledger"
)

// LayerID is the identity of a layer of the stock.
//
// The number is generated by the database: it is the counter of the layers
// and not a number of the person. The type exists so that an identifier
// never travels as a plain integer by accident.
type LayerID int64

// Layer is a layer of the stock: what a purchase brought, and what is left
// of it.
//
// The purchase is the fact of what the business bought. The layer is
// derived from it: it is the part of that purchase that the business
// still holds. The layer is never typed by the owner, and it is never a
// second truth about what was bought.
//
// The layer carries the ingredient it is of, the quantity that was bought
// with its unit, the money it cost, the day it was bought and the purchase
// it comes from.
type Layer struct {
	// ID is the identity of the layer. It is empty until the storage
	// writes the row.
	ID LayerID

	// BusinessID is the business that bought it.
	BusinessID business.ID

	// PurchaseBusinessID is the business of the purchase the layer comes
	// from.
	//
	// The layer is derived from the purchase, and it belongs to the
	// business of that purchase: a layer that claims another business is
	// not a layer of this stock, and it is refused.
	PurchaseBusinessID business.ID

	// IngredientID is the ingredient of the catalog the layer is of.
	IngredientID ingredient.ID

	// Name is the name the owner said when she bought it. The name the
	// owner reads is the one of the catalog, and the catalog is what
	// answers for it.
	Name string

	// PurchaseID is the purchase the layer comes from: the layer is
	// derived from it, and it never changes what the purchase says.
	PurchaseID ID

	// Position is the position of the line of the purchase the layer
	// comes from. It is the order the owner said the line in, and it is
	// unique inside the purchase: a layer comes from one line and from
	// no other one.
	Position int

	// Day is the day the layer was bought. It is the day of the purchase.
	Day ledger.Date

	// Bought is what the purchase brought: the quantity with its unit.
	Bought Measure

	// Left is what is left of the layer: the quantity with its unit. It
	// is never more than what was bought, and it is zero when the layer
	// is closed.
	Left Measure

	// Cost is the money the layer cost, in whole pesos. The money of the
	// book counts whole pesos, and it is the money that was paid for it.
	Cost ledger.Amount
}

// Open reports whether the layer is still open: something is left of it.
func (l Layer) Open() bool {
	return l.Left.Quantity > 0
}

// Consumed answers the layer with the quantity that is left of it after the take.
//
// The rule of the domain: the quantity that is left of a layer is what it
// held minus what the take took from it, and the quantity and its unit
// travel together: the take carries the unit of the layer it came from, and
// the answer carries it too. The quantity that is left is never more than
// what the layer bought and never less than nothing: a layer that gave
// everything it held is left with nothing.
//
// The error is ErrInvalidUnit when the take carries another unit than the
// layer holds.
func (l Layer) Consumed(take Take) (Layer, error) {
	if take.Unit != l.Left.Unit {
		return Layer{}, fmt.Errorf("%w: the take carries the unit %q and the layer holds the unit %q",
			ErrInvalidUnit, take.Unit, l.Left.Unit)
	}

	left := l.Left.Quantity - take.Quantity
	if left < 0 {
		left = 0
	}

	l.Left = Measure{Quantity: left, Unit: l.Left.Unit}

	return l, nil
}

// Checked answers the layer when it is whole, and the error when it is
// not.
//
// The rule of the domain: the layer names the ingredient of the catalog,
// it belongs to the business of its purchase, the quantity it bought is
// positive, the unit is one of the units of the book, what is left of it
// is never more than what it bought, and the money is not negative.
//
// The unit of the layer is the unit the book knows: the layer is derived,
// and the way the owner said the unit is kept in the purchase.
//
// A row that another writer broke is refused, and it is never read as a
// layer of the stock.
func (l Layer) Checked() (Layer, error) {
	if l.IngredientID == 0 {
		return Layer{}, fmt.Errorf("%w: the layer names nothing of the catalog", ErrLayerWithoutIngredient)
	}

	if l.BusinessID != l.PurchaseBusinessID {
		return Layer{}, fmt.Errorf("%w: the layer claims the business %d and it comes from the purchase of the business %d",
			ErrLayerOfAnotherBusiness, l.BusinessID, l.PurchaseBusinessID)
	}

	if l.Bought.Quantity <= 0 {
		return Layer{}, fmt.Errorf("%w: the layer bought %v", ErrInvalidQuantity, l.Bought.Quantity)
	}

	if l.Position <= 0 {
		return Layer{}, fmt.Errorf("%w: the layer is the line %d of its purchase", ErrInvalidPosition, l.Position)
	}

	unit, err := ingredient.ParseUnit(l.Bought.Unit)
	if err != nil {
		return Layer{}, err
	}

	if unit.String() != l.Bought.Unit {
		return Layer{}, fmt.Errorf("%w: the layer carries the unit %q and the book knows it as %q",
			ErrInvalidUnit, l.Bought.Unit, unit.String())
	}

	if l.Left.Quantity < 0 || l.Left.Quantity > l.Bought.Quantity {
		return Layer{}, fmt.Errorf("%w: the layer holds %v of the %v it bought",
			ErrInvalidLayer, l.Left.Quantity, l.Bought.Quantity)
	}

	if l.Left.Unit != l.Bought.Unit {
		return Layer{}, fmt.Errorf("%w: the layer holds %q and it bought %q",
			ErrInvalidLayer, l.Left.Unit, l.Bought.Unit)
	}

	if l.Cost < 0 {
		return Layer{}, fmt.Errorf("%w: the money of the layer is %d", ErrInvalidPrice, l.Cost)
	}

	return l, nil
}

// Holding is what the business holds of one ingredient in one unit.
//
// The quantity and its unit travel together: the layers of a holding are
// of the same unit, and the quantity of the holding is the sum of theirs.
// The book never adds a gram to a kilogram.
type Holding struct {
	// IngredientID is the ingredient of the catalog the holding is of.
	IngredientID ingredient.ID

	// Name is the name the owner reads of the ingredient.
	Name string

	// Unit is the unit of the quantity of the holding.
	Unit string

	// Quantity is how much of the ingredient the business holds, in the
	// unit of the holding.
	Quantity float64

	// Cost is the money of the holding, in whole pesos: the money of what
	// is left of the layers that are still open.
	Cost ledger.Amount

	// Layers are the layers of the holding, in the order they leave the
	// stock: the oldest one leaves first.
	Layers []Layer
}

// Stock is what the business holds.
//
// The stock of an ingredient is the sum of the layers that are still open,
// and the valuation is FIFO: the layers of every holding are in the order
// they leave the stock.
type Stock struct {
	// Holdings are the holdings of the business: what it holds of every
	// ingredient, in the order the layers leave the stock.
	Holdings []Holding

	// Cost is the money of the whole stock, in whole pesos.
	Cost ledger.Amount
}

// newLayer derives the layer of a line of a purchase.
//
// The purchase is the fact and the layer is derived from it: the layer
// carries the ingredient of the line, the quantity that was bought with
// its unit, the money that was paid for it, the day of the purchase, the
// purchase it comes from and the position of the line it comes from.
//
// The rule of the domain: a layer names the ingredient of the catalog. A
// line the catalog does not know has no layer, and the error is
// ErrLayerWithoutIngredient: the layer would name nothing at all.
//
// The unit of the layer is the unit the book knows: the layer is derived,
// and the way the owner said it ("kilos") is kept in the purchase, while
// the layer carries the unit of the book ("kg"). A line whose unit is not
// one of the units of the book has no layer.
//
// The position is the position of the line in the purchase: it is positive,
// and it is the order the owner said the line in.
func newLayer(bought Purchase, line Line, position int) (Layer, error) {
	if line.IngredientID == 0 {
		return Layer{}, fmt.Errorf("%w: the line %q of the purchase %d names nothing of the catalog",
			ErrLayerWithoutIngredient, line.Name, bought.ID)
	}

	if line.Measure.Quantity <= 0 {
		return Layer{}, fmt.Errorf("%w: %v", ErrInvalidQuantity, line.Measure.Quantity)
	}

	if line.Measure.Unit == "" {
		return Layer{}, fmt.Errorf("%w: the layer of the line %q carries its unit", ErrMissingUnit, line.Name)
	}

	unit, err := ingredient.ParseUnit(line.Measure.Unit)
	if err != nil {
		return Layer{}, fmt.Errorf("%w: the line %q of the purchase %d carries the unit %q",
			err, line.Name, bought.ID, line.Measure.Unit)
	}

	if position <= 0 {
		return Layer{}, fmt.Errorf("%w: the layer is the line %d of the purchase %d",
			ErrInvalidPosition, position, bought.ID)
	}

	measure := Measure{Quantity: line.Measure.Quantity, Unit: unit.String()}

	return Layer{
		BusinessID:         bought.BusinessID,
		PurchaseBusinessID: bought.BusinessID,
		IngredientID:       line.IngredientID,
		Name:               line.Name,
		PurchaseID:         bought.ID,
		Position:           position,
		Day:                bought.Day,
		Bought:             measure,
		Left:               measure,
		Cost:               line.Price.Amount(line.Measure.Quantity),
	}, nil
}

// LayersOf derives the layers of a purchase.
//
// The purchase is the fact and the layer is derived from it: every line of
// the purchase that names an ingredient of the catalog is a layer of the
// stock.
//
// A line the catalog does not know has no layer: the layer names the
// ingredient of the catalog, and the stock is the stock of the ingredients
// the business buys. The name of that line waits for the owner, and the
// quantity it brought is not in the stock until the name is resolved.
func LayersOf(bought Purchase) ([]Layer, error) {
	layers := make([]Layer, 0, len(bought.Lines))

	for position, one := range bought.Lines {
		if one.IngredientID == 0 {
			continue
		}

		layer, err := newLayer(bought, one, position+1)
		if err != nil {
			return nil, err
		}

		layers = append(layers, layer)
	}

	return layers, nil
}

// open answers the layers that are still open.
//
// The stock is the sum of the layers that are still open: a layer that is
// closed - nothing is left of it - is not in the answer.
func open(layers []Layer) []Layer {
	opened := make([]Layer, 0, len(layers))

	for _, one := range layers {
		if one.Open() {
			opened = append(opened, one)
		}
	}

	return opened
}

// OfIngredient answers the layers of one ingredient.
//
// The layers of the other ingredients are not in the answer: the stock of
// one ingredient is the sum of its own layers.
func OfIngredient(layers []Layer, of ingredient.ID) []Layer {
	held := make([]Layer, 0, len(layers))

	for _, one := range layers {
		if one.IngredientID == of {
			held = append(held, one)
		}
	}

	return held
}

// byFIFO answers the layers in the order they leave the stock.
//
// The valuation is FIFO: the oldest layer is the first one that leaves.
// The order is the day the layer was bought, and the identity of the
// purchase when two layers were bought the same day, so the answer is the
// same every time it is read.
//
// The order of the output by expiry is a different rule, and it belongs to
// the units of the bakery: the model keeps the two apart.
func byFIFO(layers []Layer) []Layer {
	ordered := make([]Layer, len(layers))
	copy(ordered, layers)

	sort.SliceStable(ordered, func(first, second int) bool {
		return leavesFirst(ordered[first], ordered[second])
	})

	return ordered
}

// leavesFirst reports whether the layer leaves the stock before the other
// one.
//
// The layer that was bought first leaves first: the valuation is FIFO. Two
// layers bought the same day are read by the identity of their purchase,
// and the identity of the layer breaks the tie.
func leavesFirst(one, other Layer) bool {
	if one.Day.Before(other.Day) {
		return true
	}

	if other.Day.Before(one.Day) {
		return false
	}

	if one.PurchaseID != other.PurchaseID {
		return one.PurchaseID < other.PurchaseID
	}

	return one.ID < other.ID
}

// TheBusinessOfTheStock answers the business whose stock is read.
//
// The rule of the domain: the stock belongs to a business, and a request
// that names no business is refused: there is no stock of nobody.
//
// The error is ErrMissingBusiness when the caller names no business.
func TheBusinessOfTheStock(own business.ID) (business.ID, error) {
	if own <= 0 {
		return 0, fmt.Errorf("%w: the stock is read for the business %d", ErrMissingBusiness, own)
	}

	return own, nil
}

// StockOf answers what the business holds.
//
// The stock of an ingredient is the sum of the layers that are still open,
// and the valuation is FIFO: the layers of every holding are in the order
// they leave the stock, and the oldest one leaves first.
//
// The layers of an ingredient that were bought in different units are held
// apart: the quantity and its unit travel together, and the book never
// adds a gram to a kilogram.
//
// The name of the holding is the name the owner reads of the ingredient,
// and it is the name of the layer when the catalog does not know it.
func StockOf(layers []Layer, catalog ingredient.Catalog) Stock {
	opened := open(layers)
	holdings := make([]Holding, 0, len(opened))
	cost := ledger.Amount(0)

	for _, one := range opened {
		name := one.Name
		if found, held := catalog.Find(one.IngredientID); held {
			name = found.Name
		}

		index := indexOf(holdings, one)
		if index < 0 {
			holdings = append(holdings, Holding{
				IngredientID: one.IngredientID,
				Name:         name,
				Unit:         one.Left.Unit,
			})
			index = len(holdings) - 1
		}

		holdings[index].Layers = append(holdings[index].Layers, one)
	}

	for index := range holdings {
		holdings[index].Layers = byFIFO(holdings[index].Layers)
		holdings[index].Quantity = quantityOf(holdings[index].Layers)
		holdings[index].Cost = costOf(holdings[index].Layers)
		cost += holdings[index].Cost
	}

	sort.SliceStable(holdings, func(first, second int) bool {
		return leavesFirst(holdings[first].Layers[0], holdings[second].Layers[0])
	})

	return Stock{Holdings: holdings, Cost: cost}
}

// indexOf answers the holding of the layer, and the index of it.
//
// The layers of an ingredient bought in the same unit are one holding: the
// quantity and its unit travel together. The answer is minus one when the
// holding is not there yet.
func indexOf(holdings []Holding, layer Layer) int {
	for index, one := range holdings {
		if one.IngredientID == layer.IngredientID && one.Unit == layer.Left.Unit {
			return index
		}
	}

	return -1
}

// quantityOf answers the quantity of the layers, in the unit they share.
func quantityOf(layers []Layer) float64 {
	quantity := 0.0

	for _, one := range layers {
		quantity += one.Left.Quantity
	}

	return quantity
}

// costOf answers the money of the layers, in whole pesos.
//
// The rule of the domain: the money of what is left of a layer is the money
// of what it bought, pro rata the quantity that is left. The stock carries
// the money of what it still holds, and never the money of what it already
// spent.
func costOf(layers []Layer) ledger.Amount {
	cost := ledger.Amount(0)

	for _, one := range layers {
		cost += one.MoneyLeft()
	}

	return cost
}
